parameters.jsCode:
// 1. ดึงข้อมูลวันที่ปัจจุบันสำหรับใช้เป็นเวลาสร้างเอกสาร (ด้านล่างรายงาน)
const today = new Date();

// คำนวณหา "เดือน/ปี" ของ "เดือนที่แล้ว" สำหรับแสดงบนหัวรายงาน
const lastMonthDate = new Date();
lastMonthDate.setMonth(lastMonthDate.getMonth() - 1); 
const targetYear = lastMonthDate.getFullYear();

// --- สร้างอาร์เรย์ชื่อเดือนภาษาไทย ---
const thaiMonths = [
    'มกราคม', 'กุมภาพันธ์', 'มีนาคม', 'เมษายน', 'พฤษภาคม', 'มิถุนายน', 
    'กรกฎาคม', 'สิงหาคม', 'กันยายน', 'ตุลาคม', 'พฤศจิกายน', 'ธันวาคม'
];
const displayMonthName = thaiMonths[lastMonthDate.getMonth()];
const displayYearTH = targetYear + 543; 

let count = 0; 
let tableRows = '';

// --- ตัวแปรสำหรับเก็บข้อมูลสรุปยอด ---
let countPending = 0;
let countInProgress = 0;
let countCompleted = 0;
let countCancelled = 0; // <--- เพิ่มตัวแปรนับยอด ยกเลิก ตรงนี้
let deviceCounts = {};

// 2. วนลูปเช็คข้อมูลทุกแถวที่ดึงมาจาก Google Sheets
for (let item of $input.all()) {

    // กรองสถานะที่ถูกลบออก (ข้ามไม่เอามาทำรายงาน)
    if (item.json['สถานะ'] === 'ถูกลบออกจากระบบ') {
        continue;
    }

    count++;

    let reportDate = item.json['วันที่แจ้งซ่อม'] || "";
    let problemDesc = item.json['รายละเอียดปัญหา'] || item.json['รายระเอียดปัญหา'] || '-';
    problemDesc = String(problemDesc).replace(/\n/g, '<br>');

    reportDate = reportDate.replace(" ", "<br><span style='color: #888; font-size: 10px;'>เวลา: ");
    if(reportDate.includes("<br>")) reportDate += " น.</span>";

    let rowBgColor = (count % 2 === 0) ? '#fafafa' : '#ffffff';

    // --- ตั้งค่าสีของข้อความสถานะ และ นับยอดตามสถานะ ---
    let statusText = item.json['สถานะ'] || '-';
    let statusColor = '#555555'; 

    if (statusText === 'รอดำเนินการ') {
        statusColor = '#F39C12';
        countPending++;
    } else if (statusText.includes('กำลังซ่อม')) {
        statusColor = '#3498db';
        countInProgress++;
    } else if (statusText.includes('ซ่อมเสร็จสิ้น')) {
        statusColor = '#27ae60';
        countCompleted++;
    } else if (statusText.includes('ยกเลิก')) { // <--- เพิ่มเงื่อนไขตรวจสอบสถานะ "ยกเลิก"
        statusColor = '#e74c3c'; // กำหนดให้เป็นสีแดง
        countCancelled++;
    }

    // --- นับยอดตามอุปกรณ์ ---
    let deviceName = item.json['อุปกรณ์'] || 'ไม่ระบุ';
    if (deviceCounts[deviceName]) {
        deviceCounts[deviceName]++;
    } else {
        deviceCounts[deviceName] = 1;
    }

    tableRows += `
    <tr style="background-color: ${rowBgColor};">
        <td style="padding: 12px 5px; border-bottom: 1px solid #eeeeee; text-align: center; color: #555; white-space: nowrap; vertical-align: top;">${item.json['ID'] || '-'}</td>
        <td style="padding: 12px 5px; border-bottom: 1px solid #eeeeee; color: #333; font-weight: bold; vertical-align: top;">${item.json['ผู้แจ้ง'] || '-'}</td>
        <td style="padding: 12px 5px; border-bottom: 1px solid #eeeeee; color: #555; vertical-align: top;">${item.json['แผนก'] || '-'}</td>
        <td style="padding: 12px 5px; border-bottom: 1px solid #eeeeee; color: #555; vertical-align: top;">${item.json['อุปกรณ์'] || '-'}</td>
        <td style="padding: 12px 5px; border-bottom: 1px solid #eeeeee; color: #555; line-height: 1.5; vertical-align: top;">${problemDesc}</td>
        <td style="padding: 12px 5px; border-bottom: 1px solid #eeeeee; text-align: center; color: #333; vertical-align: top;">${reportDate}</td>
        <td style="padding: 12px 5px; border-bottom: 1px solid #eeeeee; text-align: center; font-weight: bold; color: ${statusColor}; white-space: nowrap; vertical-align: top;">${statusText}</td>
    </tr>`;
}

// --- สร้าง HTML สรุปยอดอุปกรณ์ (เรียงจากมากไปน้อย และดัน 'อื่นๆ' ไว้ล่างสุด) ---
let sortedDevices = Object.entries(deviceCounts).sort((a, b) => {
    if (a[0] === 'อื่นๆ') return 1;  
    if (b[0] === 'อื่นๆ') return -1; 
    return b[1] - a[1];             
});
let deviceSummaryHtml = '<table style="width: 100%; border-collapse: collapse; font-size: 13px;">';
for (let i = 0; i < sortedDevices.length; i++) {
    let dev = sortedDevices[i][0];
    let devCount = sortedDevices[i][1];
    deviceSummaryHtml += `
        <tr>
            <td style="padding: 4px 0; color: #555;">${dev}</td>
            <td style="padding: 4px 0; text-align: right; font-weight: bold; color: #333;">${devCount}</td>
        </tr>`;
}
deviceSummaryHtml += '</table>';
if(sortedDevices.length === 0) deviceSummaryHtml = '<div style="color: #999;">- ไม่มีข้อมูล -</div>';

// *** ลิงก์โลโก้ ***
const logoUrl = "https://itp1.itopfile.com/ImageServer/z_itp_02102021a937/0/0/logolv-automationz-z594084060519.png"; 

const printDate = today.toLocaleDateString('th-TH', { timeZone: 'Asia/Bangkok' });
const printTime = today.toLocaleTimeString('th-TH', { timeZone: 'Asia/Bangkok', hour: '2-digit', minute:'2-digit', hour12: false });

// 3. สร้างโครงสร้าง HTML
let html = `<!DOCTYPE html>
<html lang="th">
<head>
    <meta charset="UTF-8">
    <link href="https://fonts.googleapis.com/css2?family=Sarabun:wght@300;400;600;700&display=swap" rel="stylesheet">
    <style>
        @page { size: A4 portrait; margin: 12mm 15mm; }
        @media print {
            body { -webkit-print-color-adjust: exact; print-color-adjust: exact; }
            table { page-break-inside: auto; }
            tr { page-break-inside: avoid; page-break-after: auto; }
            thead { display: table-header-group; }
            .summary-box { page-break-inside: avoid; }
        }
        .a4-container { width: 100%; max-width: 800px; margin: 0 auto; }
    </style>
</head>
<body style="font-family: 'Sarabun', sans-serif; padding: 0; margin: 0; color: #333333; background-color: #ffffff; line-height: 1.4;">

    <div class="a4-container">
        <table style="width: 100%; border-bottom: 2px solid #F39C12; padding-bottom: 10px; margin-bottom: 15px; border-collapse: collapse;">
            <tr>
                <td style="width: 50%; vertical-align: bottom;">
                    <img src="${logoUrl}" alt="Company Logo" style="max-height: 120px; object-fit: contain;">
                </td>
                <td style="width: 50%; text-align: right; vertical-align: bottom;">
                    <h2 style="margin: 0; color: #2C3E50; font-size: 20px; font-weight: 700;">รายงานสรุปปัญหาและการแจ้งซ่อม</h2>
                    <p style="margin: 5px 0 0 0; color: #7F8C8D; font-size: 14px;">เดือน: <strong style="color: #F39C12;">${displayMonthName} ${displayYearTH}</strong></p>
                </td>
            </tr>
        </table>

        <table style="border-collapse: collapse; width: 100%; font-size: 12px; table-layout: fixed; word-wrap: break-word;">
            <thead>
                <tr style="background-color: #F39C12; color: #ffffff;">
                    <th style="width: 9%; padding: 10px 5px; border-radius: 4px 0 0 0; text-align: center; border-bottom: 2px solid #d68910;">ID</th>
                    <th style="width: 11%; padding: 10px 5px; text-align: left; border-bottom: 2px solid #d68910;">ชื่อผู้แจ้ง</th>
                    <th style="width: 12%; padding: 10px 5px; text-align: left; border-bottom: 2px solid #d68910;">แผนก</th>
                    <th style="width: 16%; padding: 10px 5px; text-align: left; border-bottom: 2px solid #d68910;">อุปกรณ์</th>
                    <th style="width: 30%; padding: 10px 5px; text-align: left; border-bottom: 2px solid #d68910;">รายละเอียดปัญหา</th>
                    <th style="width: 12%; padding: 10px 5px; text-align: center; border-bottom: 2px solid #d68910;">วันที่แจ้ง</th>
                    <th style="width: 10%; padding: 10px 5px; border-radius: 0 4px 0 0; text-align: center; border-bottom: 2px solid #d68910;">สถานะ</th>
                </tr>
            </thead>
            <tbody>
                ${tableRows}
            </tbody>
        </table>

        <div class="summary-box" style="margin-top: 25px; border: 1px solid #e0e0e0; border-radius: 6px; overflow: hidden;">
            <div style="background-color: #f8f9fa; border-bottom: 1px solid #e0e0e0; padding: 10px 15px; font-weight: 600; color: #2C3E50;">
                สรุปภาพรวมปัญหา/การแจ้งซ่อม (Summary)
            </div>
            <table style="width: 100%; border-collapse: collapse;">
                <tr>
                    <td style="width: 50%; padding: 15px; vertical-align: top; border-right: 1px solid #e0e0e0;">
                        <div style="font-size: 12px; color: #7f8c8d; margin-bottom: 8px;">สรุปตามสถานะ</div>
                        <table style="width: 100%; font-size: 13px; border-collapse: collapse;">
                            <tr><td style="padding: 4px 0;"><span style="color:#F39C12;">●</span> รอดำเนินการ</td><td style="text-align: right; font-weight: bold;">${countPending}</td></tr>
                            <tr><td style="padding: 4px 0;"><span style="color:#3498db;">●</span> กำลังซ่อม</td><td style="text-align: right; font-weight: bold;">${countInProgress}</td></tr>
                            <tr><td style="padding: 4px 0;"><span style="color:#27ae60;">●</span> ซ่อมเสร็จสิ้น</td><td style="text-align: right; font-weight: bold;">${countCompleted}</td></tr>
                            <tr><td style="padding: 4px 0;"><span style="color:#e74c3c;">●</span> ยกเลิก/ลบ</td><td style="text-align: right; font-weight: bold;">${countCancelled}</td></tr>
                        </table>
                        <hr style="border: 0; border-top: 1px dashed #cccccc; margin: 10px 0;">
                        <table style="width: 100%; font-size: 14px; border-collapse: collapse;">
                            <tr>
                                <td style="font-weight: 600; color: #2C3E50;">รวมจำนวนปัญหา/การแจ้งซ่อมทั้งสิ้น</td>
                                <td style="text-align: right; font-weight: bold; color: #F39C12; font-size: 16px;">${count} <span style="font-size: 12px; font-weight: normal; color:#555;">รายการ</span></td>
                            </tr>
                        </table>
                    </td>
                    <td style="width: 50%; padding: 15px; vertical-align: top;">
                        <div style="font-size: 12px; color: #7f8c8d; margin-bottom: 8px;">สรุปตามอุปกรณ์ที่มีปัญหา/การแจ้งซ่อม</div>
                        ${deviceSummaryHtml}
                    </td>
                </tr>
            </table>
        </div>

        <div style="text-align: right; color: #95a5a6; font-size: 11px; margin-top: 15px;">
            เอกสารสร้างอัตโนมัติเมื่อวันที่: ${printDate} เวลา ${printTime} น.
        </div>
    </div>

</body>
</html>`;

// 4. ลบตัวอักษรเว้นบรรทัด (\n) ออก
html = html.replace(/\r?\n|\r/g, "");

// 5. ส่งค่าออกไป
return [{ 
    json: { 
        reportMonthString: `${displayMonthName} ${displayYearTH}`,
        totalTickets: count,
        htmlContent: html 
    } 
}];

const filteredItems = [];

// 1. คำนวณหา "เดือน/ปี" ของ "เดือนที่แล้ว"
const today = new Date();
today.setMonth(today.getMonth() - 1); // ถอยวันที่กลับไป 1 เดือน
const targetMonth = String(today.getMonth() + 1).padStart(2, '0');
const targetYear = today.getFullYear();

// รูปแบบสำหรับกรองข้อมูล เช่น /04/2026 (เพื่อให้ตรงกับรูปแบบ DD/MM/YYYY ใน Sheet)
const matchString = `/${targetMonth}/${targetYear}`; 

// ดึงก้อนข้อมูล Array แจ้งซ่อมออกมาจาก API (รองรับทั้งแบบมี .data และแบบแยก Item มาแล้ว)
const inputRecords = $input.first().json.data ? $input.first().json.data : $input.all().map(i => i.json);

// วนลูปทุกรายการแจ้งซ่อมที่เข้ามา
for (const record of inputRecords) {

  // [แก้ไข] เปลี่ยนชื่อฟิลด์ให้ตรงกับข้อมูลจริง
  let reportDate = record['วันที่แจ้งซ่อม'] || "";

  // 2. ตรวจสอบว่าเป็นข้อมูลของเดือนที่แล้วหรือไม่ ถ้าไม่ใช่ให้ข้ามไปเลย
  if (!reportDate.includes(matchString)) {
    continue;
  }

  // ตรวจสอบว่ามีข้อมูลฟิลด์ 'แผนก'
  if (record['แผนก']) {
    // ใช้ Regex ดึงเฉพาะข้อความที่อยู่ข้างในวงเล็บ (...)
    const match = record['แผนก'].match(/\(([^)]+)\)/);

    // ถ้าเจอข้อความในวงเล็บ ให้แทนที่ค่าเดิมด้วยข้อความนั้น
    if (match && match[1]) {
      record['แผนก'] = match[1]; 
    }
  }

  // เก็บ item ที่ผ่านเงื่อนไข (เดือนที่แล้ว และ ไม่ได้ถูกลบ) ลงในอาร์เรย์ (n8n ต้องการรูปแบบที่มี json ครอบ)
  filteredItems.push({ json: record });
}

// ส่งเฉพาะข้อมูลที่ผ่านการกรองและปรับแก้แล้วไปทำงานต่อ
return filteredItems;

